class ProtocolOne(unittest.TestCase):
    def test_empty_input_returns_zero_counts_and_no_receipts(self):
        self.assertEqual(accepted([], protocol="1"),
                         {"protocol": "1", "accepted_count": 0, "duplicate_count": 0, "receipts": []})

    def test_single_receipt_returned_unchanged(self):
        sole = receipt("R-1", "2026-04-01T10:00:00Z")
        self.assertEqual(accepted([sole], protocol="1"),
                         {"protocol": "1", "accepted_count": 1, "duplicate_count": 0,
                          "receipts": [sole]})

    def test_same_delivery_under_different_accounts_not_merged(self):
        receipts = [
            receipt("R-1", "2026-04-01T10:00:00Z", account_id="A"),
            receipt("R-2", "2026-04-01T09:00:00Z", account_id="B"),
        ]
        self.assertEqual(accepted(receipts, protocol="1"),
                         {"protocol": "1", "accepted_count": 2, "duplicate_count": 0,
                          "receipts": receipts})

    def test_earliest_instant_per_delivery_wins(self):
        receipts = [
            receipt("R-1", "2026-04-01T10:00:00Z"),
            receipt("R-2", "2026-04-01T08:00:00-05:00"),  # 13:00Z, latest
            receipt("R-3", "2026-04-01T09:00:00Z"),       # earliest for (A, D-1)
        ]
        self.assertEqual(accepted(receipts, protocol="1")["receipts"], [receipts[2]])

    def test_same_instant_tie_breaks_on_smallest_record_id(self):
        receipts = [
            receipt("R-2", "2026-04-01T10:00:00Z"),
            receipt("R-1", "2026-04-01T12:00:00+02:00"),  # same instant, smaller record_id
        ]
        self.assertEqual(accepted(receipts, protocol="1")["receipts"], [receipts[1]])

    def test_winners_preserve_input_order(self):
        receipts = [
            receipt("R-1", "2026-04-01T10:00:00Z", delivery_id="D-2"),
            receipt("R-2", "2026-04-01T12:00:00Z"),
            receipt("R-3", "2026-04-01T09:00:00Z"),       # earliest for (A, D-1)
        ]
        self.assertEqual(accepted(receipts, protocol="1")["receipts"], [receipts[0], receipts[2]])

    def test_counts_equal_summary_protocol_1_for_same_request(self):
        receipts = [
            receipt("R-1", "2026-04-01T10:00:00Z", account_id="A"),
            receipt("R-2", "2026-04-01T09:00:00Z", account_id="A"),
            receipt("R-3", "2026-04-01T08:00:00Z", account_id="B"),
        ]
        summary = run_cli({"command": "summary", "protocol": "1", "receipts": receipts})
        self.assertEqual(counts_only(accepted(receipts, protocol="1")), summary)

